import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionUser = (String) req.getSession().getAttribute("username");
        if (sessionUser == null) {
            resp.sendRedirect("/login");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // HTML-encode dateRange for XSS protection in error messages
        String safeDateRange = StringEscapeUtils.escapeHtml4(dateRange);

        // Build query - sort column is validated client-side via dropdown
        String query = buildReportQuery(reportType, dateRange, sortCol, sessionUser);

        resp.setContentType("text/html; charset=UTF-8");
        PrintWriter out = resp.getWriter();
        out.println("<html><head><title>Report: " + safeDateRange + "</title></head><body>");
        out.println("<h2>Report for " + sessionUser + "</h2>");
        out.println("<table border='1'>");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            out.println("<tr>");
            for (int i = 1; i <= cols; i++) {
                out.println("<th>" + meta.getColumnLabel(i) + "</th>");
            }
            out.println("</tr>");

            while (rs.next()) {
                out.println("<tr>");
                for (int i = 1; i <= cols; i++) {
                    String val = rs.getString(i);
                    out.println("<td>" + StringEscapeUtils.escapeHtml4(val) + "</td>");
                }
                out.println("</tr>");
            }
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            out.println("<p class='error'>Report generation failed. Contact support.</p>");
        }

        out.println("</table></body></html>");
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory") ||
               type.equals("returns") || type.equals("audit"));
    }

    private String buildReportQuery(String reportType, String dateRange, String sortCol, String user) {
        String baseTable = "rpt_" + reportType;
        String query = "SELECT * FROM " + baseTable + " WHERE owner='" + user + "'";

        if (dateRange != null && !dateRange.isEmpty()) {
            query += " AND created_at >= DATE_SUB(NOW(), INTERVAL " + dateRange + ")";
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            query += " ORDER BY " + sortCol;
        }

        return query;
    }
}
